/* ios-cinema-v4-js */
(()=>{const root=document.documentElement,key='go-emby-theme';const svg={sun:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.5 1.5M17.6 17.6l1.5 1.5M2 12h2M20 12h2M4.9 19.1l1.5-1.5M17.6 6.4l1.5-1.5"/></svg>',moon:'<svg viewBox="0 0 24 24"><path d="M12 3a9 9 0 1 0 9 9 7 7 0 0 1-9-9Z"/></svg>'};root.dataset.theme=localStorage.getItem(key)||(matchMedia('(prefers-color-scheme:light)').matches?'light':'dark');
function theme(){let b=document.getElementById('ios-theme-toggle-v4');if(!b){b=document.createElement('button');b.id='ios-theme-toggle-v4';b.type='button';b.setAttribute('aria-label','切换明暗模式');b.onclick=()=>{root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';localStorage.setItem(key,root.dataset.theme);theme()};document.body.appendChild(b)}b.innerHTML=root.dataset.theme==='dark'?svg.moon:svg.sun}
function structure(){const h=document.querySelector('header');if(h)h.classList.add('v4-header');const app=document.getElementById('app');if(!app)return;const login=app.querySelector('.login');if(login){if(!app.querySelector('.v4-login-stage')){const stage=document.createElement('section');stage.className='v4-login-stage';login.parentNode.insertBefore(stage,login);stage.appendChild(login)}return}const libs=app.querySelector('#libraries'),wall=app.querySelector('#wall');if(libs&&wall&&!app.classList.contains('v4-home-ready')){app.classList.add('v4-home-ready');const children=[...app.children];const bar=children.find(x=>x.classList&&x.classList.contains('bar'));const hs=[...app.querySelectorAll(':scope > h2')];const shell=document.createElement('div');shell.className='v4-home-shell';const first=wall.querySelector('.card img')||libs.querySelector('.card img');const hero=document.createElement('section');hero.className='v4-hero';const src=first&&first.src?first.src:'';hero.innerHTML='<div class="v4-hero-media"'+(src?' style="background-image:url(\''+src.replace(/'/g,'%27')+'\')"':'')+'></div><div class="v4-hero-content"><div class="v4-kicker">MACA · CINEMA</div><h1 class="v4-hero-title">你的私人影库</h1><p class="v4-hero-copy">快速进入媒体库，继续浏览与播放收藏内容。</p><div class="v4-hero-actions"><button type="button" id="v4-enter">▶&nbsp;&nbsp;浏览媒体</button></div></div>';shell.appendChild(hero);if(bar){const tb=document.createElement('div');tb.className='v4-toolbar';tb.appendChild(bar);shell.appendChild(tb)}if(libs){const sec=document.createElement('section');sec.className='v4-section';sec.innerHTML='<div class="v4-section-head"><h2>我的媒体</h2></div>';sec.appendChild(libs);shell.appendChild(sec)}if(wall){const sec=document.createElement('section');sec.className='v4-section';sec.innerHTML='<div class="v4-section-head"><h2>全部媒体</h2></div>';sec.appendChild(wall);shell.appendChild(sec)}hs.forEach(x=>x.remove());[...app.children].forEach(x=>{if(x!==shell&&x!==hero&&x!==bar&&x!==libs&&x!==wall&&x.parentNode===app)shell.appendChild(x)});app.appendChild(shell);const enter=hero.querySelector('#v4-enter');if(enter)enter.onclick=()=>wall.scrollIntoView({behavior:'smooth',block:'start'})}if(document.body.classList.contains('admin-view')&&!app.classList.contains('v4-admin-shell'))app.classList.add('v4-admin-shell');document.querySelectorAll('dialog').forEach(d=>d.classList.add('v4-dialog'))}
function watch(){structure();theme();const app=document.getElementById('app');if(app)new MutationObserver(()=>queueMicrotask(structure)).observe(app,{childList:true,subtree:true});new MutationObserver(()=>queueMicrotask(structure)).observe(document.body,{childList:true,subtree:false,attributes:true,attributeFilter:['class']})}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',watch,{once:true}):watch()})();
